// Generated by OrchestKit Claude Plugin
// Created: 2026-09-19
//
// Session metrics for the dev-only suggest mode toggle (search dialog footer).
// Pure math so the footer rendering stays trivial and the numbers stay
// testable: latency samples in ms plus the estimated USD the server reported.

export type SuggestStats = {
	/** Client-measured round-trip ms, one per completed suggest request. */
	latencies: number[];
	/** Completed suggest requests this session. */
	requests: number;
	/** Sum of server-reported estCostUsd across completed requests. */
	costUsd: number;
	/** Requests the server answered with the deterministic order. A footer
	 * showing only latency and cost cannot tell "Jev agreed" from "Jev never
	 * answered", which is what hid 72/72 timeouts in production. */
	fallbacks: number;
	/** Requests the server answered from its per-query order cache. */
	cacheHits: number;
};

export type SuggestSample = {
	costUsd: number;
	fellBack: boolean;
	cached: boolean;
};

export function createSuggestStats(): SuggestStats {
	return {
		latencies: [],
		requests: 0,
		costUsd: 0,
		fallbacks: 0,
		cacheHits: 0,
	};
}

export function recordSuggestSample(
	stats: SuggestStats,
	ms: number,
	sample: SuggestSample,
): SuggestStats {
	return {
		latencies: [...stats.latencies, ms],
		requests: stats.requests + 1,
		costUsd: stats.costUsd + sample.costUsd,
		fallbacks: stats.fallbacks + (sample.fellBack ? 1 : 0),
		cacheHits: stats.cacheHits + (sample.cached ? 1 : 0),
	};
}

/** Nearest-rank percentile; 0 on empty input. p in [0, 100]. */
export function percentile(values: readonly number[], p: number): number {
	if (values.length === 0) return 0;
	const sorted = [...values].sort((a, b) => a - b);
	const rank = Math.min(
		sorted.length,
		Math.max(1, Math.ceil((p / 100) * sorted.length)),
	);
	return sorted[rank - 1];
}
